 const enableNativePush=async()=>{if(!session||!("serviceWorker" in navigator)||!("PushManager" in window)){setNotice("Native Web Push is not supported on this browser.");return}try{const permission=Notification.permission==="granted"?"granted":await Notification.requestPermission();if(permission!=="granted"){setNotice("Notification permission was not granted.");return}const reg=await navigator.serviceWorker.ready;const existing=await reg.pushManager.getSubscription();const b64=import.meta.env.VITE_VAPID_PUBLIC_KEY;if(!b64)throw new Error("Add VITE_VAPID_PUBLIC_KEY to your frontend environment.");const pad="=".repeat((4-b64.length%4)%4);const raw=atob((b64+pad).replace(/-/g,"+").replace(/_/g,"/"));const key=Uint8Array.from(raw,c=>c.charCodeAt(0));const sub=existing||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});const json=sub.toJSON();const{data:pushData,error:pushError}=await supabase.functions.invoke("register-web-push",{body:{subscription:json}});if(pushError){let detail=pushError.message||"Request failed";const ctx=pushError.context;try{if(ctx&&typeof ctx.json==="function"){const body=await ctx.json();detail=body.error||body.message||body.msg||detail}else if(ctx&&typeof ctx.text==="function"){const bodyText=await ctx.text();if(bodyText)detail=bodyText}}catch{}const status=ctx?.status;throw new Error((status?("HTTP "+status+": "):"") + detail)}if(!pushData?.ok)throw new Error("Registration endpoint did not confirm saving this device.");setNotice("Web push notifications enabled.")}catch(e){console.error("EduToks Web Push registration failed",e);setNotice((e&&e.message)||"Unable to enable notifications. Check connection and retry.")}};
