 const finish=async(autoSubmit=false)=>{if(!quiz||result||busy)return;if(autoSubmit&&autoSubmitAttemptedRef.current)return;if(autoSubmit)autoSubmitAttemptedRef.current=true;setBusy(true);if(autoSubmit)setNotice("Time is up. Your CBT is being submitted automatically.");try{await answerSaveQueueRef.current;const payload=Object.entries(answersRef.current).map(([question_id,selected_option_id])=>({question_id,selected_option_id}));const r=await submitCbt(quiz.attempt_id,payload);setResult(r)}catch(e){setNotice((autoSubmit?"Time expired, but automatic submission failed: ":"")+ (e.message||"Unable to submit CBT. Please retry."))}finally{setBusy(false)}};
